SELECT project_name, win_tenderer, win_bid_price
FROM chatbi.bid_biz_win_bid

    deleted = 0


        AND province = #{p.provinceList[0]}


        AND (

            province = #{pItem}

        )


    AND city = #{p.city}
    AND district = #{p.district}
    AND industry = #{p.industry}
    AND info_type = #{p.infoType}
    AND channel LIKE CONCAT('%', #{p.channel}, '%')
    AND web_source_name = #{p.webSourceName}
    AND tenderer LIKE CONCAT('%', #{p.tenderer}, '%')

    AND win_tenderer LIKE CONCAT('%', #{p.winTenderer}, '%')


        AND (title LIKE CONCAT('%', #{p.keyword}, '%')
          OR project_name LIKE CONCAT('%', #{p.keyword}, '%')
          OR keywords LIKE CONCAT('%', #{p.keyword}, '%'))


    AND publish_time >= #{p.startDate}
    AND publish_time <= #{p.endDate}

    AND win_bid_price >= #{p.minBudget}
    AND win_bid_price <= #{p.maxBudget}

ORDER BY win_bid_price DESC, publish_time DESC
LIMIT #{limit}

